 for(const role of ['customer','provider','arbitrator'])button(`dispute-${role}`,own&&(!log||!approves(s,role))&&!delivered);
 button('dispute-deliver',own&&n===3&&!delivered);button('dispute-problem',own&&!!delivered&&!problemRecord);button('dispute-unauthorised',own&&!!problemRecord&&!award);button('dispute-award',own&&!!problemRecord&&!award);
