for(const [id,accepted]of [['dispute-review-reject',false],['dispute-review-accept',true]])$(id).addEventListener('click',()=>run(async()=>{requireSigning();await signedEvidence('REVIEW','customer','dispute-review-note',{award:last(session(),'AWARD').id,correction:last(session(),'CORRECTION').id,accepted});notice(accepted?'Maya signed acceptance of the corrected work. The payment report is a separate step; independent work quality is not checked.':'Maya requested another correction. The supplier can edit the correction note and sign another delivery. This rejection stays in the history.');}));
