async function copy(value,element,label){try{need(navigator.clipboard?.writeText,'Clipboard is unavailable.');await navigator.clipboard.writeText(value);notice(`${label} copied. Share it only with the people you choose.`);}catch{if($('record-details').contains(element))$('record-details').open=true;if(element.tagName==='TEXTAREA'){$('record-json-details').open=true;element.focus();element.select();}else{const range=document.createRange();range.selectNodeContents(element);const selection=getSelection();selection.removeAllRanges();selection.addRange(range);}notice(`${label} selected. Copy it manually. Nothing was sent.`);}}
async function download(bundle,filename){const raw=await P.exportHistory(bundle),url=URL.createObjectURL(new Blob([raw],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1500);notice('Download started. Check your browser\'s downloads. Open a new tab and load the file to check all terms versions and their signed updates without its private keys.');}
$('save-record').addEventListener('click',()=>run(()=>download(historyBundle(),`covenant-${current}-record.json`)));
