$('copy-code').addEventListener('click',()=>run(async()=>{const info=await P.inspectHistory(historyBundle());await copy(info.recordCode,$('record-code'),'Record code');}));
$('import-file').addEventListener('change',()=>run(async()=>{const file=$('import-file').files[0];if(!file)return;need(file.size<=512000,'Choose a saved record smaller than 512 KB.');$('import-json').value=await file.text();$('import-result').textContent='Not checked yet. Click Open and check record.';notice('File selected. Click Open and check record to verify its signed history.');}));
function fillImported(log){
 const t=log.body.terms;
 if(log.body.kind==='delegation'){$('delegation-budget').value=t.budget;$('delegation-purpose').value=t.purpose;}
 if(log.body.kind==='multiparty'){$('team-description').value=t.description;$('team-price').value=t.amount;$('team-deadline').value=new Date(t.deadline*1000).toISOString().slice(0,16);$('team-revision-rule').value=log.body.revisionRule||'ADDITIONAL_PROPOSAL';}
 if(log.body.kind==='arbitration'){
  for(const [type,id]of [['DELIVER','dispute-delivery-note'],['PROBLEM','dispute-problem-note'],['CORRECTION','dispute-correction-note'],['REVIEW','dispute-review-note'],['PAYMENT_REPORT','dispute-payment-note'],['PAYMENT_ACK','dispute-ack-note']]){const event=last(session(),type);$(id).value=event?evidenceText(log,event.body.data.evidence)||'':'';}
  const award=last(session(),'AWARD');if(award){$('dispute-share').value=award.body.data.providerBps/100;$('dispute-reason').value=award.body.data.reason;$('dispute-provider-duty').value=award.body.data.providerDuty;$('dispute-customer-duty').value=award.body.data.customerDuty;}
 }
}
$('import-record').addEventListener('click',()=>run(async()=>{const expectedId=$('expected-code').value.trim();need(!expectedId||/^[0-9a-f]{64}$/.test(expectedId),'Copy the complete 64-character record code, using lower-case letters and numbers.');let result;try{result=await P.importHistory($('import-json').value,{expectedId:expectedId||undefined});}catch(error){error.userMessage=expectedId?'The record did not pass verification or does not match the code you supplied. Nothing was loaded. Ask the sender for the correct file and code.':'The file did not pass verification. Nothing was loaded. Use a saved file from these advanced examples; the simple deal uses a different format.';$('import-result').textContent=error.userMessage;throw error;}const log=result.bundle.logs.at(-1);need(kinds.includes(log.body.kind),'This file does not contain one of these four workflow types.');backup=snapshot();current=log.body.kind;sessions={...sessions,[current]:{keys:null,log,prior:result.bundle.logs.slice(0,-1),imported:true}};fillImported(log);showWorkflow(current);const message=`Opened and checked ${result.bundle.logs.length} terms version(s) and ${result.bundle.logs.reduce((sum,item)=>sum+item.records.length,0)} signed actions. ${expectedId?'The complete record matches the code you supplied.':'No separately supplied code was checked; this does not identify the sender or confirm the record is their latest version.'} Read-only: the file contains no private signing keys.`;$('import-result').textContent=message;notice(message);}));
$('reset').addEventListener('click',()=>run(async()=>{backup=snapshot();sessions={...sessions,[current]:await newSession(current)};if(current==='delegation'){$('delegation-budget').value=100;$('delegation-purpose').value='Market research brief';$('delegation-spend').value=60;}if(current==='multiparty'){$('team-description').value="Research a local shop's market. Noor writes a brief with three sources; Eli checks the sources and edits the final page. Maya receives the approved report.";$('team-price').value=120;$('team-revision-rule').value='';$('team-deadline').value=new Date((now()+3*86400)*1000).toISOString().slice(0,16);$('team-change-result').hidden=true;}if(current==='arbitration'){$('dispute-delivery-note').value='Delivered a one-page market summary. The three sources and cost comparison table are missing.';$('dispute-problem-note').value='The summary is useful, but the agreed sources and cost table were not delivered. Please review a partial payment.';$('dispute-share').value=40;$('dispute-reason').value='The delivered summary has some value, but two required parts are missing. A partial share reflects the useful work received.';$('dispute-provider-duty').value='Supply the missing three sources and cost table. This decision does not record a release from that duty.';$('dispute-customer-duty').value='Review the completed work and arrange the proposed payment outside this demo.';$('dispute-correction-note').value='Added the missing source list and cost comparison table to the revised brief. This is a sample delivery claim for the customer to check.';$('dispute-review-note').value='';$('dispute-payment-note').value='Simulated payment report: the customer says the proposed amount was arranged outside this demo. Example reference DEMO-PAYMENT-001. No real transfer occurred here.';$('dispute-ack-note').value='North Research acknowledges this example payment report. This is a simulated receipt; no real payment has been checked.';}notice('This example has new temporary keys and a fresh record. Your other examples are unchanged. Undo restores your previous work.');}));
$('undo').addEventListener('click',()=>run(async()=>{need(backup,'There is no previous reset or import to undo.');const previous=backup;backup=snapshot();restore(previous);notice('Previous example and drafts restored. Signed approvals are unchanged.');}));
for(const id of ['import-json','expected-code'])$(id).addEventListener('input',()=>{$('import-result').textContent='Not checked yet. Click Open and check record.';});
for(const choice of document.querySelectorAll('[data-workflow]'))choice.addEventListener('click',()=>run(async()=>showWorkflow(choice.dataset.workflow,true)));
window.addEventListener('hashchange',()=>{const hash=location.hash.slice(1);if(kinds.includes(hash)&&ready)void run(async()=>showWorkflow(hash));});
