async function start(){showWorkflow(current);if(!isSecureContext||!crypto?.subtle){notice('Open this demo on the published HTTPS site or use the local server. Signing requires a secure browser context.',true);return;}try{const pairs=await Promise.all(kinds.map(async kind=>[kind,await newSession(kind)]));sessions=Object.fromEntries(pairs);$('team-deadline').value=new Date((now()+3*86400)*1000).toISOString().slice(0,16);ready=true;notice('Ready. Choose an example and follow its next step. You play every sample role; each approval is signed and checked in this tab.');await render();}catch(error){problem(error);}}
void start();
